INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01kn8jv1anenf98tp9ngn8jbyj', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', NULL, NULL, NULL, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"By late afternoon the basil was standing up again. I respect a fast recovery."}]}]}', '<p>By late afternoon the basil was standing up again. I respect a fast recovery.</p>', 'By late afternoon the basil was standing up again. I respect a fast recovery.', NULL, NULL, NULL, 'pst_01kn8jty2henf98tmnw0xzbhet', 'pst_01kn8jty2henf98tmnw0xzbhet', 1758991800, 1758991800, 1775183430, 1775183430, NULL, NULL, NULL, 1, 0, NULL, 'en', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01kn8jv2anenf98tpt6kqt3xg6', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'link', 'published', 'public', NULL, NULL, 'A night heron field guide for my walk folder', 'https://www.audubon.org/field-guide/bird/black-crowned-night-heron', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Posting this here so I can find it again the next time I see a suspiciously patient bird near the water."}]}]}', '<p>Posting this here so I can find it again the next time I see a suspiciously patient bird near the water.</p>', 'Posting this here so I can find it again the next time I see a suspiciously patient bird near the water.', NULL, NULL, 4, NULL, 'pst_01kn8jv2anenf98tpt6kqt3xg6', 1772701800, 1772701800, 1775183432, 1789965100, NULL, NULL, NULL, 1, 0, 1772701800, 'en', 'tgr_01m313qshhe4e8cms1jvmsbthy');
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01kn8jv2x0enf98tqf9hm0deme', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, 1775183432, 'A Quiet Saturday After a Busy Week', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Last week felt like six weeks compressed into five days. I spent most of it answering things, moving things, and promising myself I would slow down later. Today was the later I had in mind."}]},{"type":"paragraph","content":[{"type":"text","text":"Breakfast took an hour. I opened the windows even though it was still cold. I put the phone on the bookshelf and left it there long enough to hear the apartment settle down."}]},{"type":"moreBreak"},{"type":"paragraph","content":[{"type":"text","text":"What helped most was not turning the free day into a project. I made coffee, wiped the kitchen counter, read twenty pages, and sat in the chair by the window without trying to optimize anything."}]},{"type":"paragraph","content":[{"type":"text","text":"A good day does not always need a headline. Sometimes it only needs enough room to happen."}]}]}', '<p>Last week felt like six weeks compressed into five days. I spent most of it answering things, moving things, and promising myself I would slow down later. Today was the later I had in mind.</p><p>Breakfast took an hour. I opened the windows even though it was still cold. I put the phone on the bookshelf and left it there long enough to hear the apartment settle down.</p><!--more--><p>What helped most was not turning the free day into a project. I made coffee, wiped the kitchen counter, read twenty pages, and sat in the chair by the window without trying to optimize anything.</p><p>A good day does not always need a headline. Sometimes it only needs enough room to happen.</p>', 'Last week felt like six weeks compressed into five days. I spent most of it answering things, moving things, and promising myself I would slow down later. Today was the later I had in mind. Breakfast took an hour. I opened the windows even though it was still cold. I put the phone on the bookshelf and left it there long enough to hear the apartment settle down. What helped most was not turning the free day into a project. I made coffee, wiped the kitchen counter, read twenty pages, and sat in the chair by the window without trying to optimize anything. A good day does not always need a headline. Sometimes it only needs enough room to happen.', NULL, 'Last week felt like six weeks compressed into five days. I spent most of it answering things, moving things, and promising myself I would slow down later. Today was the later I had in mind.
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01kn8jv3exenf98tqxkzk0sjck', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'link', 'published', 'public', NULL, NULL, 'Are.na is the only bookmark pile I still revisit', 'https://www.are.na/', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Most saved links disappear into a hole. This one still feels calm enough to browse on purpose."}]}]}', '<p>Most saved links disappear into a hole. This one still feels calm enough to browse on purpose.</p>', 'Most saved links disappear into a hole. This one still feels calm enough to browse on purpose.', NULL, NULL, 4, NULL, 'pst_01kn8jv3exenf98tqxkzk0sjck', 1760537700, 1760537700, 1775183433, 1775183433, NULL, NULL, NULL, 1, 0, 1760537700, 'en', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01kn8jv4z8enf98trm559j8yeh', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, NULL, 'Bought Too Many Lemons Again', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Came home from the market with a bag of lemons, parsley, eggs, and zero idea what dinner was going to be."}]},{"type":"paragraph","content":[{"type":"text","text":"This keeps happening. I think part of me believes citrus counts as a plan."}]}]}', '<p>Came home from the market with a bag of lemons, parsley, eggs, and zero idea what dinner was going to be.</p><p>This keeps happening. I think part of me believes citrus counts as a plan.</p>', 'Came home from the market with a bag of lemons, parsley, eggs, and zero idea what dinner was going to be. This keeps happening. I think part of me believes citrus counts as a plan.', NULL, 'Came home from the market with a bag of lemons, parsley, eggs, and zero idea what dinner was going to be.
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01kn8jv5tkenf98ts7b0yqnkww', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, NULL, 'Current Tea Rotation', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The kitchen shelf is doing a lot of work right now."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Jasmine for late afternoons"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Black tea when I need to become a person quickly"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mint tea after dinner when I want the day to stop talking"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Nothing profound here. I just like having a small system for ordinary comfort."}]}]}', '<p>The kitchen shelf is doing a lot of work right now.</p><ul><li><p>Jasmine for late afternoons</p></li><li><p>Black tea when I need to become a person quickly</p></li><li><p>Mint tea after dinner when I want the day to stop talking</p></li></ul><p>Nothing profound here. I just like having a small system for ordinary comfort.</p>', 'The kitchen shelf is doing a lot of work right now. Jasmine for late afternoons Black tea when I need to become a person quickly Mint tea after dinner when I want the day to stop talking Nothing profound here. I just like having a small system for ordinary comfort.', NULL, 'The kitchen shelf is doing a lot of work right now.
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01kn8jv6c7enf98tsjzb1vw4xy', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'link', 'published', 'public', NULL, NULL, 'Derek Sivers still writes the kind of internet I want more of', 'https://sive.rs/', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Short pages, clear opinions, no inflation. I usually leave with one useful sentence and that is enough."}]}]}', '<p>Short pages, clear opinions, no inflation. I usually leave with one useful sentence and that is enough.</p>', 'Short pages, clear opinions, no inflation. I usually leave with one useful sentence and that is enough.', NULL, NULL, 4, NULL, 'pst_01kn8jv6c7enf98tsjzb1vw4xy', 1764060600, 1764060600, 1775183436, 1775183436, NULL, NULL, NULL, 1, 0, 1764060600, 'en', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01kn8jv6y3enf98tt74f3p8mmq', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, NULL, 'Desk, But Better', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I finally made the desk simple enough that I want to sit down there again."}]},{"type":"paragraph","content":[{"type":"text","text":"The rule is now: laptop, lamp, notebook, water. If something else lives there, it has to earn the space."}]}]}', '<p>I finally made the desk simple enough that I want to sit down there again.</p><p>The rule is now: laptop, lamp, notebook, water. If something else lives there, it has to earn the space.</p>', 'I finally made the desk simple enough that I want to sit down there again. The rule is now: laptop, lamp, notebook, water. If something else lives there, it has to earn the space.', NULL, 'I finally made the desk simple enough that I want to sit down there again.
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01kn8jv7f7enf98ttjcqgz8bzr', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, NULL, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Opened every window this morning and the whole place smelled like rain, old wood, and somebody else''s toast. Good start."}]}]}', '<p>Opened every window this morning and the whole place smelled like rain, old wood, and somebody else&#39;s toast. Good start.</p>', 'Opened every window this morning and the whole place smelled like rain, old wood, and somebody else''s toast. Good start.', NULL, NULL, NULL, NULL, 'pst_01kn8jv7f7enf98ttjcqgz8bzr', 1754292300, 1754292300, 1775183437, 1775183437, NULL, NULL, NULL, 1, 0, 1754292300, 'en', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01kn8jv81benf98tv36q2qgv45', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'quote', 'published', 'public', NULL, NULL, 'From Basho', 'https://en.wikiquote.org/wiki/Matsuo_Basho', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I like this more the older I get. It makes errands, walks, and ordinary Tuesdays feel less disposable."}]}]}', '<p>I like this more the older I get. It makes errands, walks, and ordinary Tuesdays feel less disposable.</p>', 'I like this more the older I get. It makes errands, walks, and ordinary Tuesdays feel less disposable.', 'Every day is a journey, and the journey itself is home.', NULL, NULL, NULL, 'pst_01kn8jv81benf98tv36q2qgv45', 1754987400, 1754987400, 1775183437, 1775183437, NULL, NULL, NULL, 1, 0, 1754987400, 'en', NULL);
