INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01kn8jw0dsenf98vaj5fcypg02', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, NULL, 'The Five-Minute Reset Is Still the Best Habit I Have', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the apartment starts feeling loud, I set a five-minute timer and do the same small loop:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"dishes into the sink"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"clothes off the chair"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"papers into one stack"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"window cracked open"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"It does not fix everything, but it changes the room enough that I stop feeling stuck in it."}]}]}', '<p>When the apartment starts feeling loud, I set a five-minute timer and do the same small loop:</p><ul><li><p>dishes into the sink</p></li><li><p>clothes off the chair</p></li><li><p>papers into one stack</p></li><li><p>window cracked open</p></li></ul><p>It does not fix everything, but it changes the room enough that I stop feeling stuck in it.</p>', 'When the apartment starts feeling loud, I set a five-minute timer and do the same small loop: dishes into the sink clothes off the chair papers into one stack window cracked open It does not fix everything, but it changes the room enough that I stop feeling stuck in it.', NULL, 'When the apartment starts feeling loud, I set a five-minute timer and do the same small loop:
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01kn8jw10aenf98vb422tdt62h', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, NULL, 'The Hallway Light Took 12 Minutes and 3 Months', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The bulb burned out in June. I meant to replace it the same day. Instead I spent three months walking through the hallway like somebody in a low-budget mystery movie."}]},{"type":"paragraph","content":[{"type":"text","text":"Today I bought the new bulb, climbed the stool, changed it, and laughed at how small the actual job was."}]},{"type":"paragraph","content":[{"type":"text","text":"This is the kind of tiny project I avoid for no good reason. The dread is usually larger than the task."}]}]}', '<p>The bulb burned out in June. I meant to replace it the same day. Instead I spent three months walking through the hallway like somebody in a low-budget mystery movie.</p><p>Today I bought the new bulb, climbed the stool, changed it, and laughed at how small the actual job was.</p><p>This is the kind of tiny project I avoid for no good reason. The dread is usually larger than the task.</p>', 'The bulb burned out in June. I meant to replace it the same day. Instead I spent three months walking through the hallway like somebody in a low-budget mystery movie. Today I bought the new bulb, climbed the stool, changed it, and laughed at how small the actual job was. This is the kind of tiny project I avoid for no good reason. The dread is usually larger than the task.', NULL, 'The bulb burned out in June. I meant to replace it the same day. Instead I spent three months walking through the hallway like somebody in a low-budget mystery movie.
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01kn8jw1jyenf98vbgfdry61m1', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'link', 'published', 'public', NULL, NULL, 'The Recurse Center manual is weirdly calming', 'https://www.recurse.com/manual', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I like reading pages where people have thought hard about how they want to work together. This one always makes me want to clean up my own habits."}]}]}', '<p>I like reading pages where people have thought hard about how they want to work together. This one always makes me want to clean up my own habits.</p>', 'I like reading pages where people have thought hard about how they want to work together. This one always makes me want to clean up my own habits.', NULL, NULL, 5, NULL, 'pst_01kn8jw1jyenf98vbgfdry61m1', 1769700000, 1769700000, 1775183464, 1775183464, NULL, NULL, NULL, 1, 0, 1769700000, 'en', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01kn8jw2yzenf98vc9xarmbqtj', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, 1775183465, 'What I Actually Use My Notebook For', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I always imagine I will use a fresh notebook for my best thoughts. In reality, it becomes useful much sooner and in messier ways."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Mostly three things"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shopping lists"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fragments I do not trust my phone with"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The first ugly version of an idea"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"That turns out to be enough. A notebook does not need to become an archive. It only needs to catch the thought before it slips away."}]}]}', '<p>I always imagine I will use a fresh notebook for my best thoughts. In reality, it becomes useful much sooner and in messier ways.</p><h2>Mostly three things</h2><ol><li><p>Shopping lists</p></li><li><p>Fragments I do not trust my phone with</p></li><li><p>The first ugly version of an idea</p></li></ol><p>That turns out to be enough. A notebook does not need to become an archive. It only needs to catch the thought before it slips away.</p>', 'I always imagine I will use a fresh notebook for my best thoughts. In reality, it becomes useful much sooner and in messier ways. Mostly three things Shopping lists Fragments I do not trust my phone with The first ugly version of an idea That turns out to be enough. A notebook does not need to become an archive. It only needs to catch the thought before it slips away.', NULL, 'I always imagine I will use a fresh notebook for my best thoughts. In reality, it becomes useful much sooner and in messier ways.
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313q94ce4e8cmdzjp993vdc', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, NULL, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"要坚持早睡早起的习惯，意味着我晚上不能吃得太晚，也不能太晚喝酒或者剧烈运动，也意味着一定要早起，这样才能早点睡着。💪"}]}]}', '<p>要坚持早睡早起的习惯，意味着我晚上不能吃得太晚，也不能太晚喝酒或者剧烈运动，也意味着一定要早起，这样才能早点睡着。💪</p>', '要坚持早睡早起的习惯，意味着我晚上不能吃得太晚，也不能太晚喝酒或者剧烈运动，也意味着一定要早起，这样才能早点睡着。💪', NULL, NULL, NULL, NULL, 'pst_01m313q94ce4e8cmdzjp993vdc', 1754573400, 1754573400, 1789965083, 1789965083, NULL, NULL, NULL, 4, 0, 1754573400, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qab0e4e8cme8fq7281df', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'quote', 'published', 'public', NULL, NULL, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"所以我现在更愿意先写一段，再决定要不要继续想下去。"}]}]}', '<p>所以我现在更愿意先写一段，再决定要不要继续想下去。</p>', '所以我现在更愿意先写一段，再决定要不要继续想下去。', '写作可以帮助你约束自己的思想。很多时候，只有当你把想法写在纸上时，看似严密的论证中的逻辑漏洞或无知之处才会显现出来。反之亦然：不动笔的思考往往会变得马虎。', NULL, NULL, NULL, 'pst_01m313qab0e4e8cme8fq7281df', 1755242400, 1755242400, 1789965085, 1789965085, NULL, NULL, NULL, 4, 0, 1755242400, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qb63e4e8cmetm7g1bsrr', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, NULL, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"推荐一下武夷路上的 All Day Coffee，用来办公心情很好。"}]}]}', '<p>推荐一下武夷路上的 All Day Coffee，用来办公心情很好。</p>', '推荐一下武夷路上的 All Day Coffee，用来办公心情很好。', NULL, NULL, NULL, NULL, 'pst_01m313qb63e4e8cmetm7g1bsrr', 1756004700, 1756004700, 1789965085, 1789965085, NULL, NULL, NULL, 4, 0, 1756004700, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qc9pe4e8cmfcwzpmw1n8', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'link', 'published', 'public', NULL, 1789965087, '通往幸福之路', 'http://hintjens.com/blog:99', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"1. 投资于你的感官","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"你的身体和心灵都需要好的\"饮食\"。自己做饭，并且做得可口。拍下你觉得美的照片。放能让你激动的音乐。穿穿着舒服的衣服。夜里，在雨中穿过这座城市。用你全部的感官，去感受生活的质地。"}]},{"type":"paragraph","content":[{"type":"text","text":"2. 做你不擅长的事","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"学习让我们感到自己活着。挑战自己，不断证明你还学得会新东西。学杂耍，学在水下憋气更久，学还原魔方。学一件乐器，弹给自己听。学画画。"}]},{"type":"paragraph","content":[{"type":"text","text":"3. 享受与人相处","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"没有什么比他人更能让我们快乐。花点时间，和你路上遇到的人说说话。友善一点，聊聊天，笑一笑。如果你住得离人群太远，就搬近些。如果你总在开车，就改变你的生活方式，让自己能走路、能骑车。走出去，融进人群里。"}]},{"type":"paragraph","content":[{"type":"text","text":"4. 成为更大事物的一部分","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"成为更大事物的一部分，会让我们感到自己有价值。找到可以参与的社群和项目，或者自己发起一个。线上线下都行。哪怕最微小的贡献，也可能改变某个人的境遇。"}]},{"type":"paragraph","content":[{"type":"text","text":"5. 把你的项目做完","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"成就感给我们希望和信心。写下你这一生完成过的事，哪怕很小的也算。然后持续更新这份清单。把手上的项目做完，再去开始新的。"}]},{"type":"paragraph","content":[{"type":"text","text":"6. 安顿好你的情绪","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"想快乐，你就必须处理负面情绪。学会在自己身上识别它们，并加以化解。愤怒、自怜、嫉妒、恐惧、憎恨、孤独……把它们放到一边，让快乐取而代之。"}]},{"type":"paragraph","content":[{"type":"text","text":"7. 重估你的时间","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"别再把时间浪费在通勤、无聊的工作、会议和电视上。只做你认为值得的事，只和你喜欢的人在一起。如果这意味着收入减少，那就减少吧。"}]},{"type":"paragraph","content":[{"type":"text","text":"8. 轻装上路","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"物质财产往往是负担，而非享受。把所有不能让你快乐的东西送人或卖掉。别让你的所有物定义你。我们生活在一个丰盛的世界里——这意味着你可以拥有得更少，而不是更多。"}]},{"type":"paragraph","content":[{"type":"text","text":"9. 无所求，尽接纳","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"最重要的是，不带欲望与索求地去探索这个世界，宽容地对待发生的一切。当你一无所求，你就不会失望；当你接纳一切，你会在每个瞬间里看见美。"}]}]}', '<p><strong>1. 投资于你的感官</strong></p><p>你的身体和心灵都需要好的&quot;饮食&quot;。自己做饭，并且做得可口。拍下你觉得美的照片。放能让你激动的音乐。穿穿着舒服的衣服。夜里，在雨中穿过这座城市。用你全部的感官，去感受生活的质地。</p><p><strong>2. 做你不擅长的事</strong></p><p>学习让我们感到自己活着。挑战自己，不断证明你还学得会新东西。学杂耍，学在水下憋气更久，学还原魔方。学一件乐器，弹给自己听。学画画。</p><p><strong>3. 享受与人相处</strong></p><p>没有什么比他人更能让我们快乐。花点时间，和你路上遇到的人说说话。友善一点，聊聊天，笑一笑。如果你住得离人群太远，就搬近些。如果你总在开车，就改变你的生活方式，让自己能走路、能骑车。走出去，融进人群里。</p><p><strong>4. 成为更大事物的一部分</strong></p><p>成为更大事物的一部分，会让我们感到自己有价值。找到可以参与的社群和项目，或者自己发起一个。线上线下都行。哪怕最微小的贡献，也可能改变某个人的境遇。</p><p><strong>5. 把你的项目做完</strong></p><p>成就感给我们希望和信心。写下你这一生完成过的事，哪怕很小的也算。然后持续更新这份清单。把手上的项目做完，再去开始新的。</p><p><strong>6. 安顿好你的情绪</strong></p><p>想快乐，你就必须处理负面情绪。学会在自己身上识别它们，并加以化解。愤怒、自怜、嫉妒、恐惧、憎恨、孤独……把它们放到一边，让快乐取而代之。</p><p><strong>7. 重估你的时间</strong></p><p>别再把时间浪费在通勤、无聊的工作、会议和电视上。只做你认为值得的事，只和你喜欢的人在一起。如果这意味着收入减少，那就减少吧。</p><p><strong>8. 轻装上路</strong></p><p>物质财产往往是负担，而非享受。把所有不能让你快乐的东西送人或卖掉。别让你的所有物定义你。我们生活在一个丰盛的世界里——这意味着你可以拥有得更少，而不是更多。</p><p><strong>9. 无所求，尽接纳</strong></p><p>最重要的是，不带欲望与索求地去探索这个世界，宽容地对待发生的一切。当你一无所求，你就不会失望；当你接纳一切，你会在每个瞬间里看见美。</p>', '1. 投资于你的感官 你的身体和心灵都需要好的"饮食"。自己做饭，并且做得可口。拍下你觉得美的照片。放能让你激动的音乐。穿穿着舒服的衣服。夜里，在雨中穿过这座城市。用你全部的感官，去感受生活的质地。 2. 做你不擅长的事 学习让我们感到自己活着。挑战自己，不断证明你还学得会新东西。学杂耍，学在水下憋气更久，学还原魔方。学一件乐器，弹给自己听。学画画。 3. 享受与人相处 没有什么比他人更能让我们快乐。花点时间，和你路上遇到的人说说话。友善一点，聊聊天，笑一笑。如果你住得离人群太远，就搬近些。如果你总在开车，就改变你的生活方式，让自己能走路、能骑车。走出去，融进人群里。 4. 成为更大事物的一部分 成为更大事物的一部分，会让我们感到自己有价值。找到可以参与的社群和项目，或者自己发起一个。线上线下都行。哪怕最微小的贡献，也可能改变某个人的境遇。 5. 把你的项目做完 成就感给我们希望和信心。写下你这一生完成过的事，哪怕很小的也算。然后持续更新这份清单。把手上的项目做完，再去开始新的。 6. 安顿好你的情绪 想快乐，你就必须处理负面情绪。学会在自己身上识别它们，并加以化解。愤怒、自怜、嫉妒、恐惧、憎恨、孤独……把它们放到一边，让快乐取而代之。 7. 重估你的时间 别再把时间浪费在通勤、无聊的工作、会议和电视上。只做你认为值得的事，只和你喜欢的人在一起。如果这意味着收入减少，那就减少吧。 8. 轻装上路 物质财产往往是负担，而非享受。把所有不能让你快乐的东西送人或卖掉。别让你的所有物定义你。我们生活在一个丰盛的世界里——这意味着你可以拥有得更少，而不是更多。 9. 无所求，尽接纳 最重要的是，不带欲望与索求地去探索这个世界，宽容地对待发生的一切。当你一无所求，你就不会失望；当你接纳一切，你会在每个瞬间里看见美。', NULL, NULL, NULL, NULL, 'pst_01m313qc9pe4e8cmfcwzpmw1n8', 1756708800, 1756708800, 1789965087, 1789965087, NULL, NULL, NULL, 4, 0, 1756708800, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qd63e4e8cmfrestyc6qf', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, NULL, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"一个人在家还是在街上更感到无聊呢？那肯定是在街上。因为一个人在家可太有意思了，在舒服的家里上网冲浪，互联网会填满所有无聊的时间；但是一个人在街上，那可就不一样了，你独自一人，被周边所有看起来幸福快乐的人包围。"}]}]}', '<p>一个人在家还是在街上更感到无聊呢？那肯定是在街上。因为一个人在家可太有意思了，在舒服的家里上网冲浪，互联网会填满所有无聊的时间；但是一个人在街上，那可就不一样了，你独自一人，被周边所有看起来幸福快乐的人包围。</p>', '一个人在家还是在街上更感到无聊呢？那肯定是在街上。因为一个人在家可太有意思了，在舒服的家里上网冲浪，互联网会填满所有无聊的时间；但是一个人在街上，那可就不一样了，你独自一人，被周边所有看起来幸福快乐的人包围。', NULL, NULL, NULL, NULL, 'pst_01m313qd63e4e8cmfrestyc6qf', 1757420100, 1757420100, 1789965087, 1789966947, NULL, NULL, NULL, 4, 0, 1757420100, 'zh-Hans', 'tgr_01m315g5kwf6ct88n3zf9m9ve1');
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qdtee4e8cmg84ey32var', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, 1789965088, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"和演讲俱乐部去安吉玩啦，超开心的！"}]}]}', '<p>和演讲俱乐部去安吉玩啦，超开心的！</p>', '和演讲俱乐部去安吉玩啦，超开心的！', NULL, NULL, NULL, NULL, 'pst_01m313qdtee4e8cmg84ey32var', 1758355200, 1758355200, 1789965088, 1789965088, NULL, NULL, NULL, 4, 0, 1758355200, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qex8e4e8cmgte4rezjpc', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'quote', 'published', 'public', NULL, NULL, '《如何记住你读过的内容》', 'https://readwise-assets.s3.amazonaws.com/media/wisereads/articles/how-to-remember-everything-you/1031.pdf', NULL, NULL, NULL, '在你能清楚复述作者的立场之前，你不许说"我同意"或"我不同意"。', NULL, NULL, NULL, 'pst_01m313qex8e4e8cmgte4rezjpc', 1759109400, 1759109400, 1789965089, 1789965089, NULL, NULL, NULL, 4, 0, 1759109400, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qfjwe4e8cmh9stpwee1b', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'link', 'published', 'public', NULL, NULL, 'CleanShot：Mac 上的截图、OCR、录屏工具', 'https://cleanshot.com/', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"用了很久的一个截图 App，它的很多交互都特别符合我的使用习惯。但首次使用需要做一些设置：比如我的习惯是截完图之后自动保存到 Downloads 文件夹，同时复制到剪贴板；然后我还希望它悬浮在左下角几秒钟——如果我需要继续高亮或者标注，我会自己点这个小窗口，不需要的话它就自行消失。"}]},{"type":"paragraph","content":[{"type":"text","text":"它默认推荐你用系统的截图快捷键，这个我也觉得挺不错的。另外它的 OCR 和录屏功能也很好用。"}]}]}', '<p>用了很久的一个截图 App，它的很多交互都特别符合我的使用习惯。但首次使用需要做一些设置：比如我的习惯是截完图之后自动保存到 Downloads 文件夹，同时复制到剪贴板；然后我还希望它悬浮在左下角几秒钟——如果我需要继续高亮或者标注，我会自己点这个小窗口，不需要的话它就自行消失。</p><p>它默认推荐你用系统的截图快捷键，这个我也觉得挺不错的。另外它的 OCR 和录屏功能也很好用。</p>', '用了很久的一个截图 App，它的很多交互都特别符合我的使用习惯。但首次使用需要做一些设置：比如我的习惯是截完图之后自动保存到 Downloads 文件夹，同时复制到剪贴板；然后我还希望它悬浮在左下角几秒钟——如果我需要继续高亮或者标注，我会自己点这个小窗口，不需要的话它就自行消失。 它默认推荐你用系统的截图快捷键，这个我也觉得挺不错的。另外它的 OCR 和录屏功能也很好用。', NULL, NULL, NULL, NULL, 'pst_01m313qfjwe4e8cmh9stpwee1b', 1759900200, 1759900200, 1789965090, 1789966949, NULL, NULL, NULL, 4, 0, 1759900200, 'zh-Hans', 'tgr_01m315g7kyf23t9d05z5ewt3qp');
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qg5de4e8cmhr30rz25q7', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, NULL, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"上生新所这个公共座椅的位置利用得很好哎。"}]}]}', '<p>上生新所这个公共座椅的位置利用得很好哎。</p>', '上生新所这个公共座椅的位置利用得很好哎。', NULL, NULL, NULL, NULL, 'pst_01m313qg5de4e8cmhr30rz25q7', 1760842200, 1760842200, 1789965090, 1789965090, NULL, NULL, NULL, 4, 0, 1760842200, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qh6ne4e8cmjawm7t0j5y', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, 1789965092, '看起来比较酷的公司们', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"这篇收集冲浪的时候遇到的「看起来」比较酷的公司，长期更新。"}]},{"type":"moreBreak"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"科技"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Automattic","marks":[{"type":"link","attrs":{"href":"https://automattic.com/","title":null,"target":"_blank"}}]},{"type":"text","text":"：WordPress、Day One 的母公司，目前也是 Tumblr 的母公司。"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Good Enough","marks":[{"type":"link","attrs":{"href":"https://goodenough.us/","title":null,"target":"_blank"}}]},{"type":"text","text":"："},{"type":"text","text":"Pika","marks":[{"type":"link","attrs":{"href":"https://pika.page/","title":null,"target":"_blank"}}]},{"type":"text","text":" 背后的博客团队。"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"投资"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CONVICTION","marks":[{"type":"link","attrs":{"href":"https://www.conviction.com/","title":null,"target":"_blank"}}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"官网很极客，有点像巴菲特他们公司的官网。"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"「我们喜欢在早期进行投资，而且往往是第一家投资方。」"}]}]}]}]}]}]}', '<p>这篇收集冲浪的时候遇到的「看起来」比较酷的公司，长期更新。</p><!--more--><h2>科技</h2><ul><li><p><a href="https://automattic.com/" target="_blank" rel="noopener noreferrer">Automattic</a>：WordPress、Day One 的母公司，目前也是 Tumblr 的母公司。</p></li><li><p><a href="https://goodenough.us/" target="_blank" rel="noopener noreferrer">Good Enough</a>：<a href="https://pika.page/" target="_blank" rel="noopener noreferrer">Pika</a> 背后的博客团队。</p></li></ul><h2>投资</h2><ul><li><p><a href="https://www.conviction.com/" target="_blank" rel="noopener noreferrer">CONVICTION</a></p><ul><li><p>官网很极客，有点像巴菲特他们公司的官网。</p></li><li><p>「我们喜欢在早期进行投资，而且往往是第一家投资方。」</p></li></ul></li></ul>', '这篇收集冲浪的时候遇到的「看起来」比较酷的公司，长期更新。 科技 Automattic https://automattic.com/ ：WordPress、Day One 的母公司，目前也是 Tumblr 的母公司。 Good Enough https://goodenough.us/ ： Pika https://pika.page/  背后的博客团队。 投资 CONVICTION https://www.conviction.com/ 官网很极客，有点像巴菲特他们公司的官网。 「我们喜欢在早期进行投资，而且往往是第一家投资方。」', NULL, '这篇收集冲浪的时候遇到的「看起来」比较酷的公司，长期更新。', NULL, NULL, 'pst_01m313qh6ne4e8cmjawm7t0j5y', 1761831900, 1761831900, 1789965092, 1789965092, NULL, NULL, NULL, 4, 0, 1761831900, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qhv0e4e8cmjsqrqxj9n5', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'quote', 'published', 'public', NULL, NULL, 'Andrew Huberman', NULL, NULL, NULL, NULL, '别问别人过得怎么样，要问他们睡得怎么样。你会从中了解到更多。', NULL, NULL, NULL, 'pst_01m313qhv0e4e8cmjsqrqxj9n5', 1762388400, 1762388400, 1789965092, 1789966949, NULL, NULL, NULL, 4, 0, 1762388400, 'zh-Hans', 'tgr_01m315g6vpf23t9cz9vcjtetxw');
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qjjze4e8cmkd4y62gh7k', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, NULL, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"最近的节奏是整整一周在家里，然后呆腻；然后一周在外面咖啡馆，然后继续呆腻，循环。"}]},{"type":"paragraph","content":[{"type":"text","text":"好多事情都充分证明了没法走极端，平衡总是最好的。"}]}]}', '<p>最近的节奏是整整一周在家里，然后呆腻；然后一周在外面咖啡馆，然后继续呆腻，循环。</p><p>好多事情都充分证明了没法走极端，平衡总是最好的。</p>', '最近的节奏是整整一周在家里，然后呆腻；然后一周在外面咖啡馆，然后继续呆腻，循环。 好多事情都充分证明了没法走极端，平衡总是最好的。', NULL, NULL, NULL, NULL, 'pst_01m313qjjze4e8cmkd4y62gh7k', 1763292600, 1763292600, 1789965093, 1789965093, NULL, NULL, NULL, 4, 0, 1763292600, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qk6ae4e8cmkrtczv0qj7', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'link', 'published', 'public', NULL, NULL, '你附近的维基百科条目', 'https://nearbywiki.org', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"很有创意，这个网站会在地图上显示所有附近拥有维基百科条目的地点。"}]}]}', '<p>很有创意，这个网站会在地图上显示所有附近拥有维基百科条目的地点。</p>', '很有创意，这个网站会在地图上显示所有附近拥有维基百科条目的地点。', NULL, NULL, NULL, NULL, 'pst_01m313qk6ae4e8cmkrtczv0qj7', 1764315900, 1764315900, 1789965094, 1789965146, NULL, NULL, NULL, 4, 0, 1764315900, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qmfse4e8cmn345pm0dgk', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'quote', 'published', 'public', NULL, NULL, 'Becky Kennedy', 'https://www.nytimes.com/interactive/2025/01/12/well/health-tips-experts.html', NULL, NULL, NULL, '我二年级的老师埃德森老师曾对我们说：「如果觉得某件事太难，那只是说明第一步还不够小。」很多时候，当我们遇到困难时，会告诉自己这是我们「不行」的迹象，或者是自己的错，结果就陷入了僵局。但当某件事在当下感觉太难时，不妨提醒自己埃德森老师给的建议。', NULL, NULL, NULL, 'pst_01m313qmfse4e8cmn345pm0dgk', 1765684800, 1765684800, 1789965095, 1789965095, NULL, NULL, NULL, 4, 0, 1765684800, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qn61e4e8cmngs2sj38vy', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, NULL, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"我发现人确实只有在无聊的时候才能想办法给自己找点事做，不能把自己填得太满。"}]},{"type":"paragraph","content":[{"type":"text","text":"比如我最近把之前欠的所有 RSS、中文的英文的、Hacker News 的热门，全部读完之后，就得给自己找点事做。刚刚让模型帮我找了一遍所有中文独立博客里 About 页面写自己人在本地的，全部列出来。我觉得我可以在里面找到一些想认识的人。"}]}]}', '<p>我发现人确实只有在无聊的时候才能想办法给自己找点事做，不能把自己填得太满。</p><p>比如我最近把之前欠的所有 RSS、中文的英文的、Hacker News 的热门，全部读完之后，就得给自己找点事做。刚刚让模型帮我找了一遍所有中文独立博客里 About 页面写自己人在本地的，全部列出来。我觉得我可以在里面找到一些想认识的人。</p>', '我发现人确实只有在无聊的时候才能想办法给自己找点事做，不能把自己填得太满。 比如我最近把之前欠的所有 RSS、中文的英文的、Hacker News 的热门，全部读完之后，就得给自己找点事做。刚刚让模型帮我找了一遍所有中文独立博客里 About 页面写自己人在本地的，全部列出来。我觉得我可以在里面找到一些想认识的人。', NULL, NULL, NULL, NULL, 'pst_01m313qn61e4e8cmngs2sj38vy', 1767622200, 1767622200, 1789965096, 1789965096, NULL, NULL, NULL, 4, 0, 1767622200, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qpfqe4e8cmpw2darbrf1', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, 1789965097, '头马演讲俱乐部初体验', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"最近连续 3 周周五晚上都会去一家听名字我都不太敢介绍给别人的组织："},{"type":"text","text":"头马","marks":[{"type":"link","attrs":{"href":"https://toastmasters.cn/","title":null,"target":"_blank"}}]},{"type":"text","text":"（Toastmasters）演讲俱乐部。Toastmasters，字面意思是「祝酒辞大师」。"}]},{"type":"paragraph","content":[{"type":"text","text":"头马成立于 1924 年，已经一百多年了（我三周前才知道头马这个词）。它是一个非营利的演讲组织，全球有一万五千多家分支俱乐部。总部提供品牌和基本流程（黑话、仪式等），各个俱乐部高度自治，会员按半年交会费，各地价格不一样。"}]},{"type":"paragraph","content":[{"type":"text","text":"听到这里是不是警报已经响起："}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"听名字和流程有一种浓浓的成功学味。"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"会费加发展会员，像邪教加传销。"}]}]}]},{"type":"moreBreak"},{"type":"paragraph","content":[{"type":"text","text":"但实际参与之后，我发现我很喜欢它的氛围：善意、欢乐、松弛、不装。第一次去的时候觉得整个流程咋那么舒服，后来才知道那一期的主持人是去年的大区演讲冠军，而且在场每个人都给了我一种特别有生命力的感觉。想想一个上班的人周五下班之后，还要兴致勃勃地来这里准备演讲，而且这里面很多人已经连续参与了四五年。"}]},{"type":"paragraph","content":[{"type":"text","text":"一个典型的头马会议大约两个半小时，基本流程是这样："}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"即兴演讲","marks":[{"type":"bold"}]},{"type":"text","text":"：主持人随机出一个话题，被点到或者自愿报名的人上台讲一到两分钟。这个环节通常最好玩，也最考验你的即兴能力。我自己感觉考验的是迅速调动大脑召回相关回忆的能力——会议前大致浏览一下自己最近的博客，对此很有帮助。"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"来宾介绍","marks":[{"type":"bold"}]},{"type":"text","text":"：每次大概有五个非会员，每人 30 秒介绍一下自己。"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"备稿演讲","marks":[{"type":"bold"}]},{"type":"text","text":"：四位事先准备好的会员上台讲三到七分钟。"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"点评","marks":[{"type":"bold"}]},{"type":"text","text":"：每位演讲者配一个指定的点评人，针对表现给出反馈。"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"角色","marks":[{"type":"bold"}]},{"type":"text","text":"：主持人串起整场；即兴主持人负责出题和串场；总评官评论整场所有人的表现（包括点评人）；计时官用绿黄红牌和铃铛提示时间；语法官记录金句和修辞；哼哈官统计「嗯」「那个」「然后」这类口头禅的次数。"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"投票","marks":[{"type":"bold"}]},{"type":"text","text":"：最后全场针对演讲和点评投票，甚至会颁奖。"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"第一次去我被 cue 了一个即兴演讲，题目是「最近解决的一件事」。第二次主动报名，题目是「如何省钱」，这个是我的舒适圈，比较好讲。"}]},{"type":"paragraph","content":[{"type":"text","text":"我喜欢这里的一点，是它提供了一个让人能舒服表达的场域，同时还精心设计了让人能持续参与下去的机制。但真正让我想参与的点并不是演讲本身。"}]},{"type":"paragraph","content":[{"type":"text","text":"大家都知道成年之后交朋友很难。城市里的活动并不少，但很多都是一次性的；即使是持续的活动，这次见到的人和上次也很可能不是同一批，甚至很多活动的设计里，根本没有听众之间交流的环节。所以很可能是去了很多次活动，但并没有认识更多的人。"}]},{"type":"paragraph","content":[{"type":"text","text":"社会学家长期以来认为，人际关系的维系更多依赖于规律性，而不是亲密程度。我们最好的朋友经常是我们的同学，就是因为同学被强制放在同一个教室里好多年，天天见一个人，自动就熟悉了——这种环境是我们成年之后很难复制的东西。"}]},{"type":"paragraph","content":[{"type":"text","text":"而头马的活动刚好凑齐了这几个条件：**固定时间，基本固定的一群人，每个人都要当着所有人的面说话。**来的人各行各业都有，我目前遇到过地理老师、皮肤科医生、律师、开发者、服装设计、银行和金融从业者、做播客的。"}]},{"type":"paragraph","content":[{"type":"text","text":"所以如果你也感兴趣，可以"},{"type":"text","text":"搜索一下你所在城市","marks":[{"type":"link","attrs":{"href":"https://toastmasters.cn/findaclub","title":null,"target":"_blank"}}]},{"type":"text","text":"的头马组织，多体验几家；如果你所在城市没有，你甚至可以考虑自己创办一个分支。一般第一次去不用花钱，大多数分会非常欢迎访客旁听。"}]},{"type":"paragraph","content":[{"type":"text","text":"P.S. 每个人偏好的东西并不一样，在我这里很不错的东西也许并不适合你，但希望每个需要社交关系的人都能找到适合自己的场域。"}]}]}', '<p>最近连续 3 周周五晚上都会去一家听名字我都不太敢介绍给别人的组织：<a href="https://toastmasters.cn/" target="_blank" rel="noopener noreferrer">头马</a>（Toastmasters）演讲俱乐部。Toastmasters，字面意思是「祝酒辞大师」。</p><p>头马成立于 1924 年，已经一百多年了（我三周前才知道头马这个词）。它是一个非营利的演讲组织，全球有一万五千多家分支俱乐部。总部提供品牌和基本流程（黑话、仪式等），各个俱乐部高度自治，会员按半年交会费，各地价格不一样。</p><p>听到这里是不是警报已经响起：</p><ol><li><p>听名字和流程有一种浓浓的成功学味。</p></li><li><p>会费加发展会员，像邪教加传销。</p></li></ol><!--more--><p>但实际参与之后，我发现我很喜欢它的氛围：善意、欢乐、松弛、不装。第一次去的时候觉得整个流程咋那么舒服，后来才知道那一期的主持人是去年的大区演讲冠军，而且在场每个人都给了我一种特别有生命力的感觉。想想一个上班的人周五下班之后，还要兴致勃勃地来这里准备演讲，而且这里面很多人已经连续参与了四五年。</p><p>一个典型的头马会议大约两个半小时，基本流程是这样：</p><ul><li><p><strong>即兴演讲</strong>：主持人随机出一个话题，被点到或者自愿报名的人上台讲一到两分钟。这个环节通常最好玩，也最考验你的即兴能力。我自己感觉考验的是迅速调动大脑召回相关回忆的能力——会议前大致浏览一下自己最近的博客，对此很有帮助。</p></li><li><p><strong>来宾介绍</strong>：每次大概有五个非会员，每人 30 秒介绍一下自己。</p></li><li><p><strong>备稿演讲</strong>：四位事先准备好的会员上台讲三到七分钟。</p></li><li><p><strong>点评</strong>：每位演讲者配一个指定的点评人，针对表现给出反馈。</p></li><li><p><strong>角色</strong>：主持人串起整场；即兴主持人负责出题和串场；总评官评论整场所有人的表现（包括点评人）；计时官用绿黄红牌和铃铛提示时间；语法官记录金句和修辞；哼哈官统计「嗯」「那个」「然后」这类口头禅的次数。</p></li><li><p><strong>投票</strong>：最后全场针对演讲和点评投票，甚至会颁奖。</p></li></ul><p>第一次去我被 cue 了一个即兴演讲，题目是「最近解决的一件事」。第二次主动报名，题目是「如何省钱」，这个是我的舒适圈，比较好讲。</p><p>我喜欢这里的一点，是它提供了一个让人能舒服表达的场域，同时还精心设计了让人能持续参与下去的机制。但真正让我想参与的点并不是演讲本身。</p><p>大家都知道成年之后交朋友很难。城市里的活动并不少，但很多都是一次性的；即使是持续的活动，这次见到的人和上次也很可能不是同一批，甚至很多活动的设计里，根本没有听众之间交流的环节。所以很可能是去了很多次活动，但并没有认识更多的人。</p><p>社会学家长期以来认为，人际关系的维系更多依赖于规律性，而不是亲密程度。我们最好的朋友经常是我们的同学，就是因为同学被强制放在同一个教室里好多年，天天见一个人，自动就熟悉了——这种环境是我们成年之后很难复制的东西。</p><p>而头马的活动刚好凑齐了这几个条件：**固定时间，基本固定的一群人，每个人都要当着所有人的面说话。**来的人各行各业都有，我目前遇到过地理老师、皮肤科医生、律师、开发者、服装设计、银行和金融从业者、做播客的。</p><p>所以如果你也感兴趣，可以<a href="https://toastmasters.cn/findaclub" target="_blank" rel="noopener noreferrer">搜索一下你所在城市</a>的头马组织，多体验几家；如果你所在城市没有，你甚至可以考虑自己创办一个分支。一般第一次去不用花钱，大多数分会非常欢迎访客旁听。</p><p>P.S. 每个人偏好的东西并不一样，在我这里很不错的东西也许并不适合你，但希望每个需要社交关系的人都能找到适合自己的场域。</p>', '最近连续 3 周周五晚上都会去一家听名字我都不太敢介绍给别人的组织： 头马 https://toastmasters.cn/ （Toastmasters）演讲俱乐部。Toastmasters，字面意思是「祝酒辞大师」。 头马成立于 1924 年，已经一百多年了（我三周前才知道头马这个词）。它是一个非营利的演讲组织，全球有一万五千多家分支俱乐部。总部提供品牌和基本流程（黑话、仪式等），各个俱乐部高度自治，会员按半年交会费，各地价格不一样。 听到这里是不是警报已经响起： 听名字和流程有一种浓浓的成功学味。 会费加发展会员，像邪教加传销。 但实际参与之后，我发现我很喜欢它的氛围：善意、欢乐、松弛、不装。第一次去的时候觉得整个流程咋那么舒服，后来才知道那一期的主持人是去年的大区演讲冠军，而且在场每个人都给了我一种特别有生命力的感觉。想想一个上班的人周五下班之后，还要兴致勃勃地来这里准备演讲，而且这里面很多人已经连续参与了四五年。 一个典型的头马会议大约两个半小时，基本流程是这样： 即兴演讲 ：主持人随机出一个话题，被点到或者自愿报名的人上台讲一到两分钟。这个环节通常最好玩，也最考验你的即兴能力。我自己感觉考验的是迅速调动大脑召回相关回忆的能力——会议前大致浏览一下自己最近的博客，对此很有帮助。 来宾介绍 ：每次大概有五个非会员，每人 30 秒介绍一下自己。 备稿演讲 ：四位事先准备好的会员上台讲三到七分钟。 点评 ：每位演讲者配一个指定的点评人，针对表现给出反馈。 角色 ：主持人串起整场；即兴主持人负责出题和串场；总评官评论整场所有人的表现（包括点评人）；计时官用绿黄红牌和铃铛提示时间；语法官记录金句和修辞；哼哈官统计「嗯」「那个」「然后」这类口头禅的次数。 投票 ：最后全场针对演讲和点评投票，甚至会颁奖。 第一次去我被 cue 了一个即兴演讲，题目是「最近解决的一件事」。第二次主动报名，题目是「如何省钱」，这个是我的舒适圈，比较好讲。 我喜欢这里的一点，是它提供了一个让人能舒服表达的场域，同时还精心设计了让人能持续参与下去的机制。但真正让我想参与的点并不是演讲本身。 大家都知道成年之后交朋友很难。城市里的活动并不少，但很多都是一次性的；即使是持续的活动，这次见到的人和上次也很可能不是同一批，甚至很多活动的设计里，根本没有听众之间交流的环节。所以很可能是去了很多次活动，但并没有认识更多的人。 社会学家长期以来认为，人际关系的维系更多依赖于规律性，而不是亲密程度。我们最好的朋友经常是我们的同学，就是因为同学被强制放在同一个教室里好多年，天天见一个人，自动就熟悉了——这种环境是我们成年之后很难复制的东西。 而头马的活动刚好凑齐了这几个条件：**固定时间，基本固定的一群人，每个人都要当着所有人的面说话。**来的人各行各业都有，我目前遇到过地理老师、皮肤科医生、律师、开发者、服装设计、银行和金融从业者、做播客的。 所以如果你也感兴趣，可以 搜索一下你所在城市 https://toastmasters.cn/findaclub 的头马组织，多体验几家；如果你所在城市没有，你甚至可以考虑自己创办一个分支。一般第一次去不用花钱，大多数分会非常欢迎访客旁听。 P.S. 每个人偏好的东西并不一样，在我这里很不错的东西也许并不适合你，但希望每个需要社交关系的人都能找到适合自己的场域。', NULL, '最近连续 3 周周五晚上都会去一家听名字我都不太敢介绍给别人的组织：头马（Toastmasters）演讲俱乐部。Toastmasters，字面意思是「祝酒辞大师」。
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qq3ee4e8cmqanq2nkhpj', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'quote', 'published', 'public', NULL, NULL, '《美国夫人》', NULL, NULL, NULL, NULL, '我们必须犯错误，这样我们才学会同情别人。', NULL, NULL, NULL, 'pst_01m313qq3ee4e8cmqanq2nkhpj', 1770521100, 1770521100, 1789965098, 1789965098, NULL, NULL, NULL, 4, 0, 1770521100, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qqr8e4e8cmqzkdryhxas', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, NULL, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"真的太享受大合唱了！"}]}]}', '<p>真的太享受大合唱了！</p>', '真的太享受大合唱了！', NULL, NULL, NULL, NULL, 'pst_01m313qqr8e4e8cmqzkdryhxas', 1771405500, 1771405500, 1789965098, 1789965098, NULL, NULL, NULL, 4, 0, 1771405500, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m313qrqre4e8cmrdep4g83wr', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'link', 'published', 'public', NULL, NULL, 'iNaturalist：爱自然社区', 'https://www.inaturalist.org/observations?view=species', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"好神奇，这个社区居然已经有 400 多万人上传过记录。"}]},{"type":"paragraph","content":[{"type":"text","text":"它是一个全球性的"},{"type":"text","text":"生物多样性记录平台 + 公民科学社区","marks":[{"type":"bold"}]},{"type":"text","text":"。流程是：你在野外拍到一只虫子、一朵花、一只鸟，上传照片（自动带上时间和 GPS 位置），社区里的其他人帮你鉴定物种。"}]}]}', '<p>好神奇，这个社区居然已经有 400 多万人上传过记录。</p><p>它是一个全球性的<strong>生物多样性记录平台 + 公民科学社区</strong>。流程是：你在野外拍到一只虫子、一朵花、一只鸟，上传照片（自动带上时间和 GPS 位置），社区里的其他人帮你鉴定物种。</p>', '好神奇，这个社区居然已经有 400 多万人上传过记录。 它是一个全球性的 生物多样性记录平台 + 公民科学社区 。流程是：你在野外拍到一只虫子、一朵花、一只鸟，上传照片（自动带上时间和 GPS 位置），社区里的其他人帮你鉴定物种。', NULL, NULL, NULL, NULL, 'pst_01m313qrqre4e8cmrdep4g83wr', 1772605800, 1772605800, 1789965099, 1789965148, NULL, NULL, NULL, 4, 0, 1772605800, 'zh-Hans', NULL);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m315g5jff6ct88mwvr080nmy', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'note', 'published', 'public', NULL, NULL, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which is more boring: being alone at home, or being alone out on the street? The street, easily."}]},{"type":"paragraph","content":[{"type":"text","text":"Alone at home is plenty interesting. You are comfortable, you are online, and the internet will fill every empty minute. Alone on the street is a different thing — you are by yourself, surrounded by everyone who looks perfectly happy."}]}]}', '<p>Which is more boring: being alone at home, or being alone out on the street? The street, easily.</p><p>Alone at home is plenty interesting. You are comfortable, you are online, and the internet will fill every empty minute. Alone on the street is a different thing — you are by yourself, surrounded by everyone who looks perfectly happy.</p>', 'Which is more boring: being alone at home, or being alone out on the street? The street, easily. Alone at home is plenty interesting. You are comfortable, you are online, and the internet will fill every empty minute. Alone on the street is a different thing — you are by yourself, surrounded by everyone who looks perfectly happy.', NULL, NULL, NULL, NULL, 'pst_01m315g5jff6ct88mwvr080nmy', 1757420100, 1757420100, 1789966947, 1789966947, NULL, NULL, NULL, 4, 0, 1757420100, 'en', 'tgr_01m315g5kwf6ct88n3zf9m9ve1');
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m315g6ttf23t9cz7gntthp05', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'quote', 'published', 'public', NULL, NULL, 'Andrew Huberman', NULL, NULL, NULL, NULL, 'Don''t ask people how they''re doing. Ask how they''re sleeping. You''ll learn more.', NULL, NULL, NULL, 'pst_01m315g6ttf23t9cz7gntthp05', 1762388400, 1762388400, 1789966949, 1789966949, NULL, NULL, NULL, 4, 0, 1762388400, 'en', 'tgr_01m315g6vpf23t9cz9vcjtetxw');
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "published_at", "last_activity_at", "created_at", "updated_at", "preview_image_key", "preview_kind", "preview_provider", "body_html_version", "quiet_reply", "thread_updated_at", "language", "translation_group_id") VALUES('pst_01m315g7jpf23t9cztdffw5w36', 'sit_01kn8jq3t4famtyg9hjd074ckr', 'link', 'published', 'public', NULL, NULL, 'CleanShot, for screenshots, OCR, and screen recording on the Mac', 'https://cleanshot.com/', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I have used this screenshot app for a long time, and most of its interactions match how I already work. It does need a little setup the first time. Mine saves to Downloads and copies to the clipboard at the same time, then floats the capture in the bottom-left corner for a few seconds — if I want to highlight or annotate, I click that little window; if I don''t, it goes away on its own."}]},{"type":"paragraph","content":[{"type":"text","text":"It suggests keeping the system screenshot shortcut, which I also think is the right default. The OCR and the screen recording are both worth having."}]}]}', '<p>I have used this screenshot app for a long time, and most of its interactions match how I already work. It does need a little setup the first time. Mine saves to Downloads and copies to the clipboard at the same time, then floats the capture in the bottom-left corner for a few seconds — if I want to highlight or annotate, I click that little window; if I don&#39;t, it goes away on its own.</p><p>It suggests keeping the system screenshot shortcut, which I also think is the right default. The OCR and the screen recording are both worth having.</p>', 'I have used this screenshot app for a long time, and most of its interactions match how I already work. It does need a little setup the first time. Mine saves to Downloads and copies to the clipboard at the same time, then floats the capture in the bottom-left corner for a few seconds — if I want to highlight or annotate, I click that little window; if I don''t, it goes away on its own. It suggests keeping the system screenshot shortcut, which I also think is the right default. The OCR and the screen recording are both worth having.', NULL, NULL, NULL, NULL, 'pst_01m315g7jpf23t9cztdffw5w36', 1759900200, 1759900200, 1789966949, 1789966949, NULL, NULL, NULL, 4, 0, 1759900200, 'en', 'tgr_01m315g7kyf23t9d05z5ewt3qp');
